/* Arquivo Operacional — apostila digital: teoria autocontida, aplicação e fontes por módulo. */

export type ApostilaExample = {
  enunciado: string;
  resolucao: string;
};

export type ApostilaReference = {
  rotulo: string;
  url: string;
  nota: string;
};

export type ApostilaSection = {
  titulo: string;
  paragrafos: string[];
  esquema?: string[];
  exemplo?: ApostilaExample;
};

export type ApostilaChapter = {
  abertura: string;
  secoes: ApostilaSection[];
  praticaAtiva: string;
  fonteOficial?: ApostilaReference;
};

const capitulo = (abertura: string, secoes: ApostilaSection[], praticaAtiva: string, fonteOficial?: ApostilaReference): ApostilaChapter => ({ abertura, secoes, praticaAtiva, fonteOficial });

